"""Build Joyce's live, reference-matched website. No PDF or poster generation.
Prices are read from the existing canonical CSV. Client material is not imported.
"""
from pathlib import Path
import csv, json, html, hashlib, base64, zipfile, io
ROOT = Path(__file__).resolve().parents[1]
SITE = ROOT / 'joyce'
VERSION = '2026-09-19-coastal-v3'
# Optional first-run transfer, removed by the release workflow after verification.
pack = ROOT / 'scripts/coastal-assets.b64'
if pack.exists():
    raw = base64.b64decode(''.join(pack.read_text().split()), validate=True)
    with zipfile.ZipFile(io.BytesIO(raw)) as z:
        for item in z.infolist():
            if item.filename not in {'coastal-portrait.avif','coastal-panorama.avif','sector-casino.avif','sector-arcade.avif','sector-sims.avif','sector-wellbeing.avif'}:
                raise ValueError('Unexpected asset path')
            (SITE/'assets'/item.filename).write_bytes(z.read(item))
services = [r for r in csv.DictReader((SITE/'rate-card.csv').open(encoding='utf-8-sig')) if r['ID'].startswith('S')]
assert len(services)==16
caps = json.loads((SITE/'content/capabilities.json').read_text())
scenarios = json.loads((SITE/'content/advisory-scenarios.json').read_text())
assert len(caps)==14 and len(scenarios)==12
for r in services:
    r['fee']=int(r['CNY_base']);r['group']='ai' if r['ID'] in ['S13','S14'] else 'partner' if r['ID'] in ['S10','S11','S12'] else 'advisory'
