def t(key): return f'<span data-i18n="{key}">{translations[key][0]}</span>'
def icon(name):
    shapes={
    'globe':'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18M5 6.5h14M5 17.5h14"/>',
    'heart':'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',
    'spark':'<path d="m12 2 2.8 6.4L22 10l-5.2 5 .8 7-5.6-3.5L6.4 22l.8-7L2 10l7.2-1.6Z"/>',
    'game':'<path d="M7 7h10c3 0 5 9 4 11s-4-1-5-3H8c-1 2-4 5-5 3S4 7 7 7Z"/><path d="M7 9v5M4.5 11.5h5M16 10h.01M19 12h.01"/>',
    'layers':'<path d="m12 3 10 5-10 5L2 8Zm-10 9 10 5 10-5M2 16l10 5 10-5"/>',
    'arrow':'<path d="M4 12h16m-6-6 6 6-6 6"/>',
    'book':'<path d="M12 5v16M2 3c4-1 7 0 10 2 3-2 6-3 10-2v16c-4-1-7 0-10 2-3-2-6-3-10-2Z"/>',
    'people':'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 4a3 3 0 0 1 0 6m2 11v-3a6 6 0 0 0-2-4"/>',
    'leaf':'<path d="M3 21C2 7 11 3 21 3c0 12-4 18-18 18Zm0 0L16 8"/>'}
    return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+shapes.get(name,shapes['spark'])+'</svg>'
